"use strict";(globalThis.webpackChunkdocs_next=globalThis.webpackChunkdocs_next||[]).push([[91322],{51004(e){e.exports=JSON.parse('{"tag":{"label":"ai","permalink":"/docs-next/pr-preview/pr-442/docs/tags/ai","allTagsPath":"/docs-next/pr-preview/pr-442/docs/tags","count":8,"items":[{"id":"blueprints/by-use-case/ai/litellm/litellm","title":"Build a Unified LLM Gateway with LiteLLM on CCE","description":"An LLM gateway acts as a centralized entry point for all interactions between applications and large language models. Rather than binding applications to specific model APIs or providers, the gateway introduces a stable interface that abstracts the underlying inference layer. This separation allows platform teams to control how requests are routed, which models are used, and where inference is executed, without requiring changes at the application level. In environments where multiple model backends coexist, such as locally hosted models on GPU infrastructure and external inference services, the gateway becomes the control plane for traffic management, policy enforcement, operational consistency and costs management.","permalink":"/docs-next/pr-preview/pr-442/docs/blueprints/by-use-case/ai/litellm/litellm"},{"id":"blueprints/by-use-case/ai/litellm/deploy-litellm-on-cce","title":"Deploy LiteLLM on CCE","description":"LiteLLM is a lightweight gateway that provides a unified interface for interacting with multiple large language model providers. It exposes an OpenAI-compatible API, allowing applications and tools to integrate once while abstracting the differences between various backends. In this role, LiteLLM sits between clients and the underlying inference layer and becomes the central control point for how models are consumed. It can route requests to different backends, such as local runtimes or external providers, without requiring changes on the client side. This enables flexibility in choosing where inference runs based on cost, performance, or data residency requirements.","permalink":"/docs-next/pr-preview/pr-442/docs/blueprints/by-use-case/ai/litellm/deploy-litellm-on-cce"},{"id":"blueprints/by-use-case/ai/litellm/deploy-ollama-on-cce","title":"Deploy Ollama on CCE","description":"Ollama is a lightweight runtime for running large language models locally. It provides a simple way to download, manage, and serve models through a REST API, without requiring complex setup or deep knowledge of model serving frameworks. This makes it well suited for environments where ease of deployment and fast iteration are important.","permalink":"/docs-next/pr-preview/pr-442/docs/blueprints/by-use-case/ai/litellm/deploy-ollama-on-cce"},{"id":"blueprints/by-use-case/ai/litellm/deploy-openwebui-on-cce","title":"Deploy Open WebUI on CCE","description":"Open WebUI is a self-hosted web interface for interacting with large language models. It provides a chat-based UI that connects to OpenAI-compatible APIs, making it easy to test and use different models without building custom frontends. In this blueprint, Open WebUI acts as the user-facing layer on top of the LLM gateway. It allows users and teams to interact with the models exposed through LiteLLM, without needing to know where those models are running. This makes it a practical tool for internal adoption, enabling non-developers and developers alike to access LLM capabilities through a browser.","permalink":"/docs-next/pr-preview/pr-442/docs/blueprints/by-use-case/ai/litellm/deploy-openwebui-on-cce"},{"id":"blueprints/by-use-case/ai/deploy-the-nvidia-gpu-operator-on-cce","title":"Deploy the NVIDIA GPU Operator on CCE","description":"The NVIDIA GPU Operator is a critical tool for effectively managing GPU resources in Kubernetes clusters. It serves as an abstraction layer over Kubernetes APIs, automating tasks such as dynamic provisioning, driver updates, resource allocation, and optimization for GPU-intensive workloads, thereby simplifying the deployment and management of GPU-accelerated applications. Its functionality extends to dynamic provisioning of GPUs on demand, managing driver updates, optimizing resource allocation for varied workloads, and integrating with monitoring tools for comprehensive insights into GPU usage and health. This guide outlines how to deploy the NVIDIA GPU Operator on CCE cluster. The process involves preparing GPU nodes, installing necessary components, configuring the cluster for GPU support, deploying an application leveraging GPUs, and verifying functionality.","permalink":"/docs-next/pr-preview/pr-442/docs/blueprints/by-use-case/ai/deploy-the-nvidia-gpu-operator-on-cce"},{"id":"blueprints/by-use-case/ai/deploy-vllm-production-stack-on-cce","title":"Deploy vLLM Production Stack on CCE","description":"vLLM is an open-source inference and serving engine for large language models. It is designed to improve serving throughput and GPU memory efficiency, mainly through PagedAttention, continuous batching, prefix caching, and an OpenAI-compatible serving interface.","permalink":"/docs-next/pr-preview/pr-442/docs/blueprints/by-use-case/ai/deploy-vllm-production-stack-on-cce"},{"id":"blueprints/by-industry/healthcare/fuse-ai-open-telekom-cloud","title":"Fuse-AI: e-Health from the Cloud","description":"Fuse-AI is making medical diagnosis easier with artificial intelligence. A second opinion from the T Cloud Public saves radiologists time, improves the quality of their diagnoses and reduces costs. The Hamburg-based entrepreneurs founded their start-up in 2015 and developed artificial intelligence that can detect indications of cancer \u2013 such as carcinomas \u2013 on MRI scan and assess whether a tumor is benign or malignant. And that doesn\u2019t just save doctors time. \u201cThe biggest advantage is the improved quality of a diagnosis,\u201d says Maximilian Waschka, one of the four Fuse-AI founders. \u201cOur algorithm helps radiologists notice abnormalities on thousands of images more reliably.\u201d The start-up estimates that its e-health solution can save health insurers at least 10 percent of the costs associated with MRI examinations.","permalink":"/docs-next/pr-preview/pr-442/docs/blueprints/by-industry/healthcare/fuse-ai-open-telekom-cloud"},{"id":"blueprints/by-use-case/ai/securely-expose-remote-ollama-endpoints-to-your-development-machine","title":"Securely Expose Remote Ollama Endpoints to your Development Machine","description":"Exposing Ollama endpoints directly from your cloud environment to your local development machine can be highly beneficial, especially when it comes to optimizing the use of expensive resources like GPUs and integrating them with local cost-effective development hardware.","permalink":"/docs-next/pr-preview/pr-442/docs/blueprints/by-use-case/ai/securely-expose-remote-ollama-endpoints-to-your-development-machine"}],"unlisted":false}}')}}]);